package com.modernarmory.registry;

import java.util.HashMap;
import java.util.Map;

import com.modernarmory.ModernArmory;

import net.minecraft.core.registries.Registries;
import net.minecraft.sounds.SoundEvent;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

/**
 * Every sound event of the mod. Shared sounds (calibre reports, bullet cracks, UI clicks) are
 * constants here; each gun's own mechanical sounds ("&lt;gun&gt;_reload", "_reload_empty", "_cycle",
 * "_shell", generated by tools/soundgen/make_sounds.py to the gun's animation lengths) are
 * registered through {@link #mechanical(String)} by the gun's SoundSet ({@code SoundSets.forGun}),
 * so adding a gun needs no edit here.
 */
public final class ModSounds {
    public static final DeferredRegister<SoundEvent> SOUNDS = DeferredRegister.create(Registries.SOUND_EVENT, ModernArmory.MODID);

    /** Gunshots carry: audible ~192 blocks away. */
    public static final DeferredHolder<SoundEvent, SoundEvent> M4_FIRE = fixed("m4_fire", 192f);
    /** Supersonic "snap" heard when a bullet passes close by. */
    public static final DeferredHolder<SoundEvent, SoundEvent> BULLET_CRACK = fixed("bullet_crack", 24f);
    public static final DeferredHolder<SoundEvent, SoundEvent> DRY_FIRE = fixed("dry_fire", 12f);
    public static final DeferredHolder<SoundEvent, SoundEvent> M4_RELOAD = fixed("m4_reload", 16f);
    public static final DeferredHolder<SoundEvent, SoundEvent> M4_RELOAD_EMPTY = fixed("m4_reload_empty", 16f);
    public static final DeferredHolder<SoundEvent, SoundEvent> M2010_RELOAD_EMPTY = fixed("m2010_reload_empty", 16f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_SELECT = fixed("fire_select", 8f);
    /** Suppressed .300 Win Mag shot followed by the bolt being worked. */
    public static final DeferredHolder<SoundEvent, SoundEvent> M2010_FIRE = fixed("m2010_fire", 96f);
    /** Unsuppressed .300 Win Mag (M2010 with its can removed) + bolt. */
    public static final DeferredHolder<SoundEvent, SoundEvent> M2010_FIRE_LOUD = fixed("m2010_fire_loud", 224f);
    /** Suppressed 5.56: still a sharp supersonic crack, much less blast. */
    public static final DeferredHolder<SoundEvent, SoundEvent> M4_FIRE_SUPPRESSED = fixed("m4_fire_suppressed", 64f);
    public static final DeferredHolder<SoundEvent, SoundEvent> M2010_RELOAD = fixed("m2010_reload", 16f);
    public static final DeferredHolder<SoundEvent, SoundEvent> RICOCHET = fixed("ricochet", 32f);

    // ---- calibre reports (gun.Report): range grows with the muzzle blast; suppressed ones keep
    // the supersonic crack (9 mm M882 is subsonic, so suppressed it is mostly action noise)
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_9MM_PISTOL = fixed("fire_9mm_pistol", 160f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_9MM_SMG = fixed("fire_9mm_smg", 160f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_9MM_SUPPRESSED = fixed("fire_9mm_suppressed", 32f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_68 = fixed("fire_68", 208f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_68_SUPPRESSED = fixed("fire_68_suppressed", 72f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_762 = fixed("fire_762", 208f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_762_SUPPRESSED = fixed("fire_762_suppressed", 72f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_300WM = fixed("fire_300wm", 224f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_300WM_SUPPRESSED = fixed("fire_300wm_suppressed", 96f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_338 = fixed("fire_338", 240f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_338_SUPPRESSED = fixed("fire_338_suppressed", 112f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_50BMG = fixed("fire_50bmg", 256f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_12GA = fixed("fire_12ga", 176f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_50AE = fixed("fire_50ae", 176f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_44MAG = fixed("fire_44mag", 176f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_762X39 = fixed("fire_762x39", 200f);
    public static final DeferredHolder<SoundEvent, SoundEvent> FIRE_45ACP = fixed("fire_45acp", 160f);

    /** Per-gun mechanical sounds by name, registered on first request. */
    private static final Map<String, DeferredHolder<SoundEvent, SoundEvent>> MECHANICAL = new HashMap<>();

    // ---- grenades (tools/soundgen/make_sounds.py: grenade_sounds)
    public static final DeferredHolder<SoundEvent, SoundEvent> GRENADE_PIN = mechanical("grenade_pin");
    public static final DeferredHolder<SoundEvent, SoundEvent> GRENADE_SPOON = mechanical("grenade_spoon");
    public static final DeferredHolder<SoundEvent, SoundEvent> GRENADE_BOUNCE = mechanical("grenade_bounce");
    public static final DeferredHolder<SoundEvent, SoundEvent> SMOKE_HISS = mechanical("smoke_hiss");
    public static final DeferredHolder<SoundEvent, SoundEvent> THERMITE_BURN = mechanical("thermite_burn");
    /** Ringing ears after an M84 (played only for the player who was hit). */
    public static final DeferredHolder<SoundEvent, SoundEvent> FLASH_RING = mechanical("flash_ring");
    /** The M84's 170-180 dB bang: heard a long way off. */
    public static final DeferredHolder<SoundEvent, SoundEvent> FLASHBANG = fixed("flashbang", 160f);


    // ---- hit markers (tools/soundgen/hit_markers.py), played only to the shooter: server.HitMarkers
    public static final DeferredHolder<SoundEvent, SoundEvent> HIT_BODY = mechanical("hit_body");
    public static final DeferredHolder<SoundEvent, SoundEvent> HIT_HEAD = mechanical("hit_head");
    /** A bullet hitting body armour (tools/soundgen/armor_hits.py): soft aramid, and hard plates. */
    public static final DeferredHolder<SoundEvent, SoundEvent> ARMOR_HIT_SOFT = mechanical("armor_hit_soft");
    public static final DeferredHolder<SoundEvent, SoundEvent> ARMOR_HIT_PLATE = mechanical("armor_hit_plate");

    // ---- drones (tools/soundgen/drone_sounds.py)
    /** Rotor noise loops: a quadcopter is heard ~40 m off (the FPV's high-revving props a little further). */
    public static final DeferredHolder<SoundEvent, SoundEvent> DRONE_ROTOR_SCOUT = fixed("drone_rotor_scout", 40f);
    public static final DeferredHolder<SoundEvent, SoundEvent> DRONE_ROTOR_FPV = fixed("drone_rotor_fpv", 48f);
    /** Controller / drone status chirps (link up, deployed, picked up, refused). */
    public static final DeferredHolder<SoundEvent, SoundEvent> DRONE_BEEP = mechanical("drone_beep");
    /** Target tagged by the scout. */
    public static final DeferredHolder<SoundEvent, SoundEvent> DRONE_SPOT = mechanical("drone_spot");
    /** The FPV's charge is live. */
    public static final DeferredHolder<SoundEvent, SoundEvent> DRONE_ARM = mechanical("drone_arm");
    /** Link lost / low battery warning. */
    public static final DeferredHolder<SoundEvent, SoundEvent> DRONE_WARNING = mechanical("drone_warning");
    /** Airframe hitting something / breaking up. */
    public static final DeferredHolder<SoundEvent, SoundEvent> DRONE_CRASH = fixed("drone_crash", 24f);
    /** The FPV's charge going off (on top of the explosion). */
    public static final DeferredHolder<SoundEvent, SoundEvent> DRONE_DETONATION = fixed("drone_detonation", 192f);

    // ---- laser turret (tools/soundgen/laser_sounds.py)
    /** The laser firing: a cooling-pump and power hum, ~1 s, replayed while the beam is on. */
    public static final DeferredHolder<SoundEvent, SoundEvent> LASER_HUM = fixed("laser_hum", 40f);
    /** The target sizzling under the beam. */
    public static final DeferredHolder<SoundEvent, SoundEvent> LASER_BURN = fixed("laser_burn", 24f);
    /** Track / boarding chirp in the operator's headset. */
    public static final DeferredHolder<SoundEvent, SoundEvent> LASER_LOCK = mechanical("laser_lock");
    /** Overheat warning in the operator's headset. */
    public static final DeferredHolder<SoundEvent, SoundEvent> LASER_OVERHEAT = mechanical("laser_overheat");

    /**
     * A gun's own mechanical sound (reload, action cycle, shell insert), audible ~16 blocks. Called
     * while the catalogs initialise (mod construction), before the sound registry is built.
     */
    public static synchronized DeferredHolder<SoundEvent, SoundEvent> mechanical(String name) {
        return MECHANICAL.computeIfAbsent(name, n -> fixed(n, 16f));
    }

    private static DeferredHolder<SoundEvent, SoundEvent> fixed(String name, float range) {
        return SOUNDS.register(name, () -> SoundEvent.createFixedRangeEvent(ModernArmory.id(name), range));
    }

    private ModSounds() {}
}
